import { NO_ERRORS_SCHEMA } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { HttpClientTestingModule } from '@angular/common/http/testing';
import { RouterTestingModule } from '@angular/router/testing';
import { NoopAnimationsModule } from '@angular/platform-browser/animations';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { ToastrModule } from 'ngx-toastr';

// Top-level beforeEach applies to every spec: provides the app-wide modules
// that component specs generated by the CLI don't declare themselves.
beforeEach(() => {
  TestBed.configureTestingModule({
    imports: [
      HttpClientTestingModule,
      RouterTestingModule,
      NoopAnimationsModule,
      FormsModule,
      ReactiveFormsModule,
      ToastrModule.forRoot()
    ],
    // Shallow rendering for unit tests; the strict production build verifies
    // that every element in every template is known.
    schemas: [NO_ERRORS_SCHEMA]
  });
});
